//! Web4 HTTP middleware: wire x402 payment gating and did:key authentication
//! into the framework's middleware chain.
//!
//!   - `x402Middleware` — routes without a valid payment proof get a 402
//!     (invoice generated by `on_invoice`), invalid proofs get 403; the
//!     default verifier is fail-closed (never accepts).
//!   - `didAuthMiddleware` — verifies a did:key signature from headers and
//!     writes `did` / `user_id` attrs for downstream handlers.

const std = @import("std");
const api = @import("../api/Server.zig");
const x402_mod = @import("x402.zig");
const did_mod = @import("did.zig");

/// Config for `x402Middleware`. `verifier` must be the production payment
/// verifier (on-chain check, allow-list); the helper stays fail-closed when
/// the verifier rejects. `on_invoice` builds the 402 invoice per request
/// (route-based pricing); when absent a generic invoice is returned.
pub const X402Config = struct {
    verifier: x402_mod.PaymentVerifier = x402_mod.verifyPaymentReject,
    on_invoice: ?*const fn (*api.Context, std.mem.Allocator) anyerror!x402_mod.Invoice = null,
    /// When set, only paths starting with this prefix are gated (allows
    /// per-route protection with global middleware).
    path_prefix: ?[]const u8 = null,
    invoice_id: []const u8 = "web4-access",
    payee_did: []const u8 = "did:key:z6Mk-placeholder",
    amount: u64 = 1000000,
    currency: x402_mod.Currency = .usdc,
    description: []const u8 = "Web4 API access",
};

/// x402 payment gate: no proof → 402 + invoice; invalid proof → 403; valid →
/// downstream handler.
pub fn x402Middleware(cfg: *X402Config) api.Middleware {
    return .{
        .func = struct {
            fn mw(ctx: *api.Context, next: api.HandlerFn, userdata: ?*anyopaque) anyerror!void {
                const c: *X402Config = @ptrCast(@alignCast(userdata.?));
                if (c.path_prefix) |p| {
                    if (!std.mem.startsWith(u8, ctx.path, p)) {
                        try next(ctx);
                        return;
                    }
                }
                if (ctx.header("x402-tx-hash")) |tx| {
                    const invoice_id = ctx.header("x402-invoice-id") orelse {
                        try ctx.sendError(402, "missing invoice id");
                        return;
                    };
                    const proof = x402_mod.PaymentProof{
                        .tx_hash = try ctx.allocator.dupe(u8, tx),
                        .invoice_id = try ctx.allocator.dupe(u8, invoice_id),
                    };
                    defer {
                        ctx.allocator.free(proof.tx_hash);
                        ctx.allocator.free(proof.invoice_id);
                    }
                    if (x402_mod.verifyWith(c.verifier, proof)) {
                        try ctx.setAttr("x402_paid", "true");
                        try next(ctx);
                        return;
                    }
                    try ctx.sendError(403, "invalid payment proof");
                    return;
                }
                const invoice = if (c.on_invoice) |f|
                    try f(ctx, ctx.allocator)
                else
                    x402_mod.Invoice{
                        .id = c.invoice_id,
                        .payee_did = c.payee_did,
                        .amount = c.amount,
                        .currency = c.currency,
                        .deadline = @import("../core/Time.zig").monotonicNowSeconds() + 3600,
                        .description = c.description,
                    };
                try x402_mod.writePaymentRequired(ctx, ctx.allocator, invoice);
            }
        }.mw,
        .user_data = cfg,
    };
}

/// Config for `didAuthMiddleware`.
pub const DidAuthConfig = struct {
    /// Headers carrying the DID, message and base64 signature.
    did_header: []const u8 = "x-did",
    message_header: []const u8 = "x-did-message",
    signature_header: []const u8 = "x-did-signature",
    /// When set, only paths starting with this prefix require DID auth.
    path_prefix: ?[]const u8 = null,
};

/// did:key authentication: verifies a signature over `message`; on success
/// writes `did` and `user_id` attrs. Missing/invalid credentials → 401.
pub fn didAuthMiddleware(cfg: *DidAuthConfig) api.Middleware {
    return .{
        .func = struct {
            fn mw(ctx: *api.Context, next: api.HandlerFn, userdata: ?*anyopaque) anyerror!void {
                const c: *DidAuthConfig = @ptrCast(@alignCast(userdata.?));
                if (c.path_prefix) |p| {
                    if (!std.mem.startsWith(u8, ctx.path, p)) {
                        try next(ctx);
                        return;
                    }
                }
                const did = ctx.header(c.did_header) orelse {
                    try ctx.sendError(401, "missing DID");
                    return;
                };
                const message = ctx.header(c.message_header) orelse {
                    try ctx.sendError(401, "missing message");
                    return;
                };
                const sig_b64 = ctx.header(c.signature_header) orelse {
                    try ctx.sendError(401, "missing signature");
                    return;
                };
                var key = did_mod.resolve(ctx.allocator, did) catch {
                    try ctx.sendError(401, "unresolvable DID");
                    return;
                };
                defer ctx.allocator.free(key.did);
                const dec = std.base64.standard.Decoder;
                const sig_len = dec.calcSizeForSlice(sig_b64) catch {
                    try ctx.sendError(401, "invalid signature encoding");
                    return;
                };
                const signature = try ctx.allocator.alloc(u8, sig_len);
                defer ctx.allocator.free(signature);
                dec.decode(signature, sig_b64) catch {
                    try ctx.sendError(401, "invalid signature encoding");
                    return;
                };
                if (!try key.verify(message, signature)) {
                    try ctx.sendError(401, "invalid signature");
                    return;
                }
                try ctx.setAttr("did", did);
                try ctx.setAttr("user_id", did);
                try next(ctx);
            }
        }.mw,
        .user_data = cfg,
    };
}

test "x402Middleware gates unauthenticated requests with 402" {
    const allocator = std.testing.allocator;
    var cfg = X402Config{};
    const mw = x402Middleware(&cfg);
    var ctx = try api.Context.init(allocator, .GET, "/api/paid");
    defer ctx.deinit();
    try mw.func(&ctx, struct {
        fn h(_: *api.Context) anyerror!void {}
    }.h, mw.user_data);
    try std.testing.expectEqual(@as(u16, 402), ctx.status_code);
    try std.testing.expect(ctx.responded);
}

test "x402Middleware allows valid proofs" {
    const allocator = std.testing.allocator;
    var cfg = X402Config{ .verifier = x402_mod.verifyPaymentAllowAll };
    const mw = x402Middleware(&cfg);
    var ctx = try api.Context.init(allocator, .GET, "/api/paid");
    defer ctx.deinit();
    try ctx.headers.put(try allocator.dupe(u8, "x402-tx-hash"), try allocator.dupe(u8, "0xabc"));
    try ctx.headers.put(try allocator.dupe(u8, "x402-invoice-id"), try allocator.dupe(u8, "inv-1"));
    const State = struct {
        var reached = false;
    };
    try mw.func(&ctx, struct {
        fn h(_: *api.Context) anyerror!void {
            State.reached = true;
        }
    }.h, mw.user_data);
    try std.testing.expect(State.reached);
    try std.testing.expectEqual(@as(u16, 200), ctx.status_code);
    try std.testing.expect(!ctx.responded);
}
